import{_ as n}from"./chunks/image12.BRgDBKom.js";import{_ as a,o as r,c as i,am as t,j as o}from"./chunks/framework.CenUaW7a.js";const s="/projects/AiMechaM1/en/advanced-kit/assets/video1.SjqMV6gV.mp4",l="/projects/AiMechaM1/en/advanced-kit/assets/image2.DJnjmPXj.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image3.CeDk_eBB.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image4.DgmMRX1a.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image5.BjYXHWmU.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image6.DLVkLZMr.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image7.CqE5zvZd.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image8.DbPDNb6m.png",u="/projects/AiMechaM1/en/advanced-kit/assets/image9.BuxTpzY2.png",f="/projects/AiMechaM1/en/advanced-kit/assets/image10.DEQSPRQK.png",v="/projects/AiMechaM1/en/advanced-kit/assets/image11.Vzb7cTCI.png",I=JSON.parse('{"title":"3.28 Lesson 28: Intelligent Control and Machine Execution","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.28 Lesson 28 Intelligent Control and Machine Execution.md","filePath":"docs/3. Course materials/3.28 Lesson 28 Intelligent Control and Machine Execution.md"}'),b={name:"docs/3. Course materials/3.28 Lesson 28 Intelligent Control and Machine Execution.md"};function y(x,e,w,_,k,C){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="_3-28-lesson-28-intelligent-control-and-machine-execution" tabindex="-1">3.28 Lesson 28: Intelligent Control and Machine Execution <a class="header-anchor" href="#_3-28-lesson-28-intelligent-control-and-machine-execution" aria-label="Permalink to &quot;3.28 Lesson 28: Intelligent Control and Machine Execution&quot;">​</a></h1><h2 id="_3-28-1-lesson-introduction" tabindex="-1">3.28.1 Lesson Introduction <a class="header-anchor" href="#_3-28-1-lesson-introduction" aria-label="Permalink to &quot;3.28.1 Lesson Introduction&quot;">​</a></h2><p>This lesson focuses on integrating large speech models with robot control to explore natural language-driven hardware execution. Starting from everyday scenarios such as &quot;feeling cold and turning on lights or closing curtains&quot;, the curriculum contrasts traditional voice control with intelligent comprehension powered by large models. Core topics cover three essential technologies: automatic speech recognition known as ASR, text-to-speech synthesis known as TTS, and large model semantic parsing, alongside the Model Context Protocol tool configuration mechanism that enables large models to control hardware, including lights, motors, and robotic arms. Practical exercises implement a voice control system supporting natural language control over lighting, robot movement, and robotic arm actions, introducing the AIresult variable and the &quot;ok&quot; feedback protocol. Moving from voice conversation to physical voice control upgrades large models into physical control portals, laying a solid foundation for embodied intelligence.</p><h2 id="_3-28-2-learning-objectives" tabindex="-1">3.28.2 Learning Objectives <a class="header-anchor" href="#_3-28-2-learning-objectives" aria-label="Permalink to &quot;3.28.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the acoustic feature matching principles of automatic speech recognition, abbreviated as ASR. Master prosody modeling and vocoder technology in text-to-speech synthesis, abbreviated as TTS, alongside the working mechanism and role of the MCP tool-calling protocol.</p><p><strong>2.</strong> Program the initialization and execution of the online large model mode. Use the AIresult variable to temporarily store large model recognition results. Write conditional branches for MCP tool evaluation and execution.</p><p><strong>3.</strong> Establish an interactive mindset for natural language-driven hardware control. Cultivate system design capabilities for intent parsing and action mapping, and enhance logical programming skills for parallel multi-tool invocation.</p><p><strong>4.</strong> Connect smart home voice control, intelligent in-vehicle voice assistants, industrial robot voice commands, and accessible assistive devices to real-world application scenarios, comprehending the transformative value of large speech models in human-robot interaction.</p><h2 id="_3-28-3-preparation" tabindex="-1">3.28.3 Preparation <a class="header-anchor" href="#_3-28-3-preparation" aria-label="Permalink to &quot;3.28.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li>AiMecha M1 Mecanum-Wheel Car Advanced Kit</li><li>Type-C data cable</li><li>Computer × 1</li><li>Remote controller</li></ul><p><strong>Software Preparation</strong>:</p><ul><li>WonderLab graphical programming software</li></ul><p><strong>Three Speech Technology Principles</strong>:</p><ul><li><p><strong>Automatic Speech Recognition or ASR</strong>: Technology that converts audio signals into text. After capturing audio, the microphone decomposes the signal into acoustic features matched against phoneme and word patterns learned during large model training to ultimately output text. Powered by large models, the system adapts to diverse accents and background noise.</p></li><li><p><strong>Text-to-Speech Synthesis or TTS</strong>: Technology that converts text into natural speech. Large models analyze text semantics and prosody to predict pronunciation, pitch, pauses, and emotion for every word, generating highly lifelike audio waveforms via vocoders.</p></li><li><p><strong>Speech Interaction</strong>: A comprehensive framework integrating speech recognition, large language models, and speech synthesis: capturing spoken audio → converting audio into text → analyzing semantics and generating a response via the large model → synthesizing the response into speech → playing the audio aloud to achieve end-to-end natural conversation.</p></li></ul><p><strong>MCP Tool-Calling Mechanism</strong>:</p><ul><li><p><strong>Definition</strong>: Model Context Protocol, abbreviated as MCP, is a standardized protocol enabling large models to invoke external tools, control hardware, query data, and execute operations.</p></li><li><p><strong>Workflow</strong>: Receiving a spoken voice command → parsing intent via the large model → determining the required tools → returning tool-calling commands → executing hardware operations locally → sending execution feedback to the large model → generating a final voice response.</p></li><li><p><strong>Default Tool Set</strong>: RGB LED control, ultrasonic RGB light control, buzzer playback, battery voltage query, motor speed control, movement distance control, robotic arm motion control, and gripper angle control.</p></li></ul><p><strong>Wiring Instructions</strong>:</p><ul><li><p>Connect the K230 screen module to <strong>port A</strong> of the controller.</p></li><li><p>Connect the three bus servos in series to bus ports S1 or S2, where ID 1 controls the gripper, ID 2 controls the forearm, and ID 3 controls the upper arm.</p></li><li><p>Connect the RGB LEDs to the corresponding lighting effect ports.</p></li><li><p>Connect the ultrasonic sensor to <strong>port K</strong>.</p></li></ul><p><strong>Key Programming Concepts</strong>:</p><ul><li><p><strong>AIresult Variable</strong>: Temporarily stores large model recognition results to prevent data discrepancies caused by repeated reads, ensuring data consistency within a single frame.</p></li><li><p><strong>Send Response Result</strong>: Feeds back &quot;result: ok&quot; to the large model after executing a tool, completing the closed loop of request, execution, and feedback.</p></li><li><p><strong>Tool Name Evaluation</strong>: <code>Whether the default MCP tool name XX exists</code> block to determine which tool the large model intends to invoke.</p></li></ul><h2 id="_3-28-4-practical-implementation" tabindex="-1">3.28.4 Practical Implementation <a class="header-anchor" href="#_3-28-4-practical-implementation" aria-label="Permalink to &quot;3.28.4 Practical Implementation&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This project builds a natural language-driven machine control system powered by large models, centered around a voice-driven MCP tool-calling closed loop. The K230 microphone captures voice commands and uploads them to the cloud via Wi-Fi, where cloud ASR transcribes the audio into text, and the large model parses semantic intent and sentiment to determine the required MCP tools. The decision-making layer receives structured tool commands, caches them in the AIresult variable, and dispatches them sequentially: setting color values for the RGB LEDs, rotational speeds for the motors, directions and distances for chassis movement, and target coordinates and durations for the robotic arm. Once each hardware module in the execution layer completes its action, it returns &quot;result: ok&quot; so the large model can generate voice feedback. Program Logic: The entire system forms a closed loop encompassing voice input → semantic parsing → tool invocation → hardware execution → result feedback → voice reply, mapping natural language directly to physical actions and illustrating the embodied intelligence concept where &quot;the large model acts as the brain and MCP acts as the nervous system.&quot;</p>',24),o("p",null,[o("video",{controls:"",playsinline:"",preload:"metadata",src:s})],-1),t('<p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Mode configuration</td><td style="text-align:center;"><img loading="lazy" height="67" width="451" src="'+l+'" class="common_img" style="width:360px;aspect-ratio:451 / 67;"></td><td style="text-align:left;">Switches to the online large model mode to enable cloud AI and MCP tool capabilities.</td></tr><tr><td style="text-align:center;">MCP configuration</td><td style="text-align:center;"><img loading="lazy" height="65" width="377" src="'+c+'" class="common_img" style="width:280px;aspect-ratio:377 / 65;"></td><td style="text-align:left;">Loads the default MCP tool set and registers all controllable hardware tools.</td></tr><tr><td style="text-align:center;">Detection control</td><td style="text-align:center;"><img loading="lazy" height="65" width="232" src="'+d+'" class="common_img" style="width:160px;aspect-ratio:232 / 65;"></td><td style="text-align:left;">Starts the large model voice interaction and tool-calling engine.</td></tr><tr><td style="text-align:center;">Data synchronization</td><td style="text-align:center;"><img loading="lazy" height="64" width="318" src="'+h+'" class="common_img" style="width:210px;aspect-ratio:318 / 64;"></td><td style="text-align:left;">Synchronizes the latest large model recognition results and tool-calling requests.</td></tr><tr><td style="text-align:center;">Result detection</td><td style="text-align:center;"><img loading="lazy" height="74" width="400" src="'+p+'" class="common_img" style="width:210px;aspect-ratio:400 / 74;"></td><td style="text-align:left;">Determines whether the large model has returned new tool-calling commands.</td></tr><tr><td style="text-align:center;">Result retrieval</td><td style="text-align:center;"><img loading="lazy" height="76" width="434" src="'+g+'" class="common_img" style="width:210px;aspect-ratio:434 / 76;"></td><td style="text-align:left;">Reads the complete recognition results and stores them in the <code>AIresult</code> variable.</td></tr><tr><td style="text-align:center;">Tool evaluation</td><td style="text-align:center;"><img loading="lazy" height="51" width="624" src="'+m+'" class="common_img" style="width:470px;aspect-ratio:624 / 51;"></td><td style="text-align:left;">Evaluates whether the large model has invoked a specified tool, such as RGB LEDs or motor speed.</td></tr><tr><td style="text-align:center;">Parameter retrieval</td><td style="text-align:center;"><img loading="lazy" height="58" width="415" src="'+u+'" class="common_img" style="width:300px;aspect-ratio:415 / 58;"></td><td style="text-align:left;">Extracts specific tool parameter values from the recognition results, such as RGB values, motor speed, or distance.</td></tr><tr><td style="text-align:center;">Result feedback</td><td style="text-align:center;"><img loading="lazy" height="56" width="532" src="'+f+'" class="common_img" style="width:460px;aspect-ratio:532 / 56;"></td><td style="text-align:left;">Sends tool execution success feedback to the large model to complete the invocation closed loop.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task: Complete Voice Control System for Lighting and Car Movement</strong></p><ul><li><p>Startup initialization: Upon startup, wait 6 seconds and play note B5 for a 1/8 beat as the initial startup tone. Initialize port A, configure the Wi-Fi SSID and password, load the default MCP configuration, set the operating mode to online large model, initialize the linkage robotic arm, and play note B6 for a 1/8 beat as the readiness prompt tone.</p></li><li><p>Main loop structure: Start detection execution, and repeatedly update and save result data.</p></li><li><p>Result retrieval branch: If <code>Does result exist?</code> returns true, assign the retrieved recognition result to the AIresult variable to cache data and maintain consistency across the frame.</p></li><li><p>RGB LED control branch: If AIresult contains the default MCP tool name for setting the RGB LED, set the red, green, and blue channels of the RGB LED to the corresponding red, green, and blue parameter values extracted from AIresult, then send a response result with dictionary key <code>result</code> and value <code>ok</code>.</p></li><li><p>Ultrasonic RGB light branch: If AIresult contains the default MCP tool name for the glowing ultrasonic RGB light, set the ultrasonic sensor RGB light to the extracted RGB values and send the response result <code>ok</code>, following the same principle as the onboard RGB LED.</p></li><li><p>Buzzer control branch: If AIresult contains the default MCP tool name for the buzzer, extract the buzzer frequency and duration in milliseconds, activate the buzzer accordingly, and send the response result <code>ok</code>.</p></li><li><p>Motor speed branch: If AIresult contains the default MCP tool name for motor speed, set the front-left, rear-left, front-right, and rear-right wheel speeds of the Mecanum-wheel car to the respective motor speed parameters extracted from AIresult, and send the response result <code>ok</code>.</p></li><li><p>Movement distance branch: If AIresult contains the default MCP tool name for movement distance, command the Mecanum-wheel car to translate at the rotational speed in rpm, toward the directional angle in degrees, and for the distance in centimeters extracted from AIresult, then send the response result <code>ok</code>.</p></li><li><p>Robotic arm control branch: If AIresult contains the default MCP tool name for robotic arm motion, move the robotic arm end effector to the forward-backward Y-axis coordinate in millimeters and vertical Z-axis coordinate in millimeters extracted from AIresult over the specified duration in milliseconds, and send the response result <code>ok</code>.</p></li><li><p>Gripper control branch: If AIresult contains the default MCP tool name for the mechanical gripper, set bus servo ID 1 to the target angle in degrees over the duration in milliseconds extracted from AIresult, and send the response result <code>ok</code>.</p></li></ul><img loading="lazy" height="654" width="1474" src="'+v+'" class="common_img" style="width:1000px;aspect-ratio:1474 / 654;"><p><strong>Program Design Key Points</strong></p><ul><li><p>Variable caching: Store the recognition result in the AIresult variable first and read from this variable across all conditional branches. Never call the direct retrieval block repeatedly across branches, as doing so causes data inconsistency.</p></li><li><p>Parallel multi-tool execution: Place multiple tool evaluation branches in parallel so a single composite command can invoke several tools concurrently, such as turning on lights while moving.</p></li><li><p>Feedback closed loop: Send a <code>result: ok</code> response immediately after each tool finishes executing. The large model waits for this confirmation before generating a voice reply and treats the task as failed if no confirmation arrives.</p></li><li><p>Natural language command examples: <code>Hello Hiwonder, turn the lights blue</code>, <code>Move forward for one second</code>, <code>Turn left 10 centimeters</code>, <code>Raise the robotic arm</code>, and <code>Open the gripper</code>.</p></li><li><p>Intent parsing: The large model comprehends implicit or casual expressions, for example, automatically increasing brightness when hearing <code>Make it brighter</code> or spinning in place when hearing <code>Spin around</code>.</p></li></ul><p><strong>Voice Control Sample Phrases</strong></p><ul><li><p>Lighting Control: <code>Turn the lights red</code>, <code>Make the lights brighter</code>, <code>Turn off the RGB lights</code>, <code>Turn the ultrasonic lights blue</code>.</p></li><li><p>Movement Control: <code>Move forward for one second</code>, <code>Turn left 10 centimeters</code>, <code>Move backward 5 centimeters</code>, <code>Spin right in place</code>.</p></li><li><p>Robotic Arm Control: <code>Raise the robotic arm</code>, <code>Open the gripper</code>, <code>Extend the robotic arm forward</code>.</p></li><li><p>Composite Commands: <code>Turn on the green light, then move forward 20 centimeters</code>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1qESIR7n_mxv3oQTrZhNbBTnPKVOk-yT4?usp=sharing" target="_blank" rel="noreferrer">Program Files/Intelligent Control Execution</a>.</strong></p></div></li></ul><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and plug the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button on the top toolbar of the software and select the COM port corresponding to CH340 from the dropdown list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to compile and download the program to the mecha controller.</p></li></ul><img loading="lazy" height="508" width="960" src="'+n+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-28-5-expansion-and-advancement" tabindex="-1">3.28.5 Expansion and Advancement <a class="header-anchor" href="#_3-28-5-expansion-and-advancement" aria-label="Permalink to &quot;3.28.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Expansion Project 1: Affective Voice Interaction System</strong></p><p>Design an emotional response mode: when receiving the command &quot;In a hurry, move faster&quot;, the car recognizes the urgency keyword and automatically increases movement speed. When receiving &quot;Take it slow, be careful&quot;, the system reduces speed and enables obstacle avoidance mode. When receiving &quot;Great job&quot;, the controller plays cheerful music and flashes colored lights. Explore how large models comprehend emotional semantics to make robot responses more lifelike, demonstrating the value of affective computing in natural language interaction and creating a warmer human-robot interaction experience.</p><p><strong>Expansion Project 2: Multi-Step Task Voice Orchestration System</strong></p><p>Design a composite task voice command system, such as &quot;First, turn the lights red, then move forward 30 centimeters, turn left, and finally raise the robotic arm&quot;. Verify whether the large model can accurately parse multiple action steps within a single long command and execute them sequentially. Explore the long-command parsing capabilities of large models, master the technical principles of task planning and action sequence orchestration, and lay the groundwork for subsequent embodied intelligence collaboration lessons.</p><h2 id="_3-28-6-q-a" tabindex="-1">3.28.6 Q&amp;A <a class="header-anchor" href="#_3-28-6-q-a" aria-label="Permalink to &quot;3.28.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What are the differences and connections among automatic speech recognition, text-to-speech synthesis, and speech interaction?</strong></p><p><strong>Answer</strong>: These three concepts form a <strong>progressive hierarchy</strong>, where each preceding technology serves as the foundation for the next, and the latter integrates and upgrades the former.</p><p><strong>Q2: What is MCP tool calling?</strong></p><p><strong>Answer</strong>: MCP is a standardized interface protocol that enables large models to <strong>invoke external tools and hardware</strong>, functioning as both a &quot;translator&quot; and a &quot;switchboard&quot; operator between AI models and physical hardware.</p><h2 id="_3-28-7-technical-support-and-discussion" tabindex="-1">3.28.7 Technical Support and Discussion <a class="header-anchor" href="#_3-28-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.28.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',25)])])}const A=a(b,[["render",y]]);export{I as __pageData,A as default};
